L<Protobuf::Message> and support C<new()>, C<serialize()>, C<parse()>,
C<to_json()>, C<from_json()>, C<to_text()>, and C<to_perl()>.

=head1 MESSAGES

=head2 Google::Cloud::Chronicle::V1::Feed::FeedPack

FeedPack is a logical container for related LogTypes for which feeds can be
configured.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The resource name of the feed pack.
Format:
projects/{project}/locations/{location}/instances/{instance}/feedPacks/{feed_pack}

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Output only. The display name of the feed pack.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Output only. The description of the feed pack.

=item * C<< $msg->icon() >> / C<< $msg->icon($value) >>

Type: C<Bytes>

Output only. The icon image of the content pack in base64 in png format.

=item * C<< $msg->categories() >> / C<< $msg->categories($value) >>

Type: C<String>

Output only. Categories the featured content is associated with. In case of
product feed packs, there will be only one category.

=item * C<< $msg->pack_type() >> / C<< $msg->pack_type($value) >>

Type: C<Enum> (L<Google::Cloud::Chronicle::V1::FeedPack::PackType>)

Output only. Type of pack.

=item * C<< $msg->pack_log_types() >> / C<< $msg->pack_log_types($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::PackLogType>)

Output only. Log types featured in the pack.

=item * C<< $msg->hidden() >> / C<< $msg->hidden($value) >>

Type: C<Bool>

Output only. Whether the feed pack should be displayed in the Feeds Page.

=item * C<< $msg->pack_documentation() >> / C<< $msg->pack_documentation($value) >>

Type: C<String>

Output only. Pack specific documentation in markdown format.

=back

=head3 Enum: FeedPack::PackType

=over 4

=item * C<PACK_TYPE_UNSPECIFIED> => C<0>

=item * C<PRODUCT_BASED> => C<1>

=item * C<USECASE_BASED> => C<2>

=item * C<ONBOARDING> => C<3>

=back

