primary request (e.g., fetching full event details for a list of basic
alert IDs). Note: In MVP, the child depth fan-out limit is capped at 1.

=back

=head2 Google::Cloud::Chronicle::V1::Feed::CustomAPIRequestConfig

Configuration for the outgoing API request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->endpoint_path() >> / C<< $msg->endpoint_path($value) >>

Type: C<String>

Required. Enter the specific API route appended to the Base URL to fetch
the data (e.g., /v1/alerts).

=item * C<< $msg->http_method() >> / C<< $msg->http_method($value) >>

Type: C<Enum> (L<Google::Cloud::Chronicle::V1::CustomAPIRequestConfig::HttpMethod>)

Required. Select the type of action to perform on the API endpoint (usually
GET to retrieve data or POST to submit a query).

=item * C<< $msg->request_body() >> / C<< $msg->request_body($value) >>

Type: C<String>

Optional. Provide the data payload sent to the API to specify what
information you want, typically formatted in JSON.

=item * C<< $msg->query_parameters() >> / C<< $msg->query_parameters($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::HeaderKeyValue>)

Optional. Add extra filters or settings appended to the end of the URL
(e.g., ?status=critical).

=item * C<< $msg->custom_headers() >> / C<< $msg->custom_headers($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::HeaderKeyValue>)

Optional. Define specialized key-value pairs sent with the request, often
used for custom API versioning or specific vendor requirements.

=item * C<< $msg->max_requests_per_minute() >> / C<< $msg->max_requests_per_minute($value) >>

Type: C<Int32>

Optional. Set a safety limit to ensure the connector does not exceed the
third-party vendor's API rate limits.

=back

=head3 Enum: CustomAPIRequestConfig::HttpMethod

=over 4

=item * C<HTTP_METHOD_UNSPECIFIED> => C<0>

=item * C<GET> => C<1>

=item * C<POST> => C<2>

=back

=head2 Google::Cloud::Chronicle::V1::Feed::CustomAPIResponseConfig

Configuration for handling the API response.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->target_data_path() >> / C<< $msg->target_data_path($value) >>

Type: C<String>

Required. Enter the exact path in the API's response payload where the list
of target log entries is located.

=back

=head2 Google::Cloud::Chronicle::V1::Feed::CustomAPICheckpointConfig

Checkpoint configuration to enable sequential (cursor-based) polling.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->none_strategy() >> / C<< $msg->none_strategy($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPICheckpointConfig::NoneStrategy>)

Fetch all available data in one go without tracking progress.

=item * C<< $msg->latest_timestamp_strategy() >> / C<< $msg->latest_timestamp_strategy($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPICheckpointConfig::LatestTimestampStrategy>)

Track the timestamp of the newest record to fetch newer ones next.

=item * C<< $msg->latest_record_strategy() >> / C<< $msg->latest_record_strategy($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPICheckpointConfig::LatestRecordStrategy>)

Track the highest record ID to fetch only new records next.

=item * C<< $msg->iterator_strategy() >> / C<< $msg->iterator_strategy($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPICheckpointConfig::IteratorStrategy>)

Use progress tokens provided by the API.

=back

=head2 Google::Cloud::Chronicle::V1::Feed::CustomAPIPagination

Pagination strategy for the request.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->none() >> / C<< $msg->none($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPIPagination::NonePagination>)

Fetch data in a single request without paging.

=item * C<< $msg->token() >> / C<< $msg->token($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPIPagination::TokenPagination>)

Use tokens (custom keys) to get the next page of data.

=item * C<< $msg->link() >> / C<< $msg->link($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPIPagination::LinkPagination>)

Follow links provided in the response to get more data.

=item * C<< $msg->offset() >> / C<< $msg->offset($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPIPagination::OffsetPagination>)

Skip a set number of records to get the next set.

=item * C<< $msg->page_number() >> / C<< $msg->page_number($value) >>

Type: C<Message> (L<Google::Cloud::Chronicle::V1::Feed::CustomAPIPagination::PageNumberPagination>)

Go to the next page number (e.g., page 2).

=back

